#!/bin/bash
# One layer-swap test checkpoint (docs/recall_surgery_ambitious.md §11; scripts/korbi/production/layer_swap.py):
#   <ROOT>/<arm>/ckpt/iter_<BASE_IT>   = <SRC>/iter_<BASE_IT> (hard links) + LAYERS from <SRC>/iter_<DONOR_IT>,
#                                        or LAYERS' output projections zeroed (DONOR_IT=zero)
#   <ROOT>/<arm>/ckpt/latest_checkpointed_iteration.txt = BASE_IT, written after layer_swap.py's read-back.
# Run from a synced snapshot as the 1-node pool jobs of config/experiments/korbi/production/layer_swap_build_mn5.yaml
# (generated by scripts/korbi/production/gen_layer_swap.py).
#   ARM=<arm> BASE_IT=<it> DONOR_IT=<it>|zero LAYERS=attn6|attn1|ckda1|mixall layer_swap_build.sh
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
SIF=${SIF:-/gpfs/projects/ehpc533/users/korbip/hybrid_v019/container/MegatronTraining-hybrid-ep_x86_64_202610161948.sif}
SRC=${SRC:-/gpfs/scratch/ehpc533/hybrid_nucleus/production/main_mhc4/ambitious_e360_eng80_v4_2ph_hd256/ckpt_eval}
ROOT=${ROOT:-/gpfs/scratch/ehpc533/hybrid_nucleus/production/layer_swap}
: "${ARM:?}" "${BASE_IT:?}" "${DONOR_IT:?}" "${LAYERS:?}"
case $ROOT in */main_mhc4*) echo "refusing to write below the main run ($ROOT)" >&2; exit 2 ;; esac
if [ -n "${SINGULARITY_CONTAINER:-}${APPTAINER_CONTAINER:-}" ]; then PY=(python3); else PY=(singularity exec --nv "$SIF" python3); fi
it() { printf 'iter_%07d' "$1"; }
OUT=$ROOT/$ARM/ckpt
TRACK=$OUT/latest_checkpointed_iteration.txt
if [ -f "$TRACK" ]; then
  [ "$(tr -d '[:space:]' < "$TRACK")" = "$BASE_IT" ] && { echo "$ARM: done (tracker $BASE_IT)"; exit 0; }
  echo "$TRACK holds $(cat "$TRACK"), not $BASE_IT" >&2; exit 3
fi
DST=$OUT/$(it "$BASE_IT")
[ -e "$DST" ] && { echo "$ARM: removing the partial attempt $DST"; rm -rf "$DST"; }
args=(build --base "$SRC/$(it "$BASE_IT")" --dst "$DST" --layers "$LAYERS")
[ "$DONOR_IT" = zero ] || args+=(--donor "$SRC/$(it "$DONOR_IT")")
"${PY[@]}" "$HERE/layer_swap.py" "${args[@]}"
echo "$BASE_IT" > "$TRACK"
echo "$ARM: tracker $BASE_IT"
